function renderGallery(category){const list=galleryData.filter(p=>p.category===category);document.getElementById('gallery-title').textContent=categoryLabels[category]+' Fotoğrafları';document.getElementById('gallery-count').textContent=list.length+' fotoğraf · Büyütmek için bir fotoğrafa dokunun.';const grid=document.getElementById('photo-grid');grid.replaceChildren();list.forEach((p,i)=>{const b=document.createElement('button');b.className='photo-card';b.setAttribute('aria-label',categoryLabels[category]+' fotoğrafı '+(i+1)+' büyüt');const img=document.createElement('img');img.onerror=()=>{if(img.src!==p.url){img.onerror=null;img.src=p.url}};img.src=photoURL(p.id);img.alt='Tuval Cam '+categoryLabels[category].toLocaleLowerCase('tr')+' uygulama fotoğrafı '+(i+1);img.loading=i<4?'eager':'lazy';img.width=p.width;img.height=p.height;const caption=document.createElement('span');caption.textContent=categoryLabels[category]+' · '+String(i+1).padStart(2,'0');b.append(img,caption);b.onclick=()=>openPhoto(list,i,b);grid.append(b)});const reviews=document.getElementById('product-reviews');reviews.replaceChildren();const heading=document.createElement('h3');heading.textContent=categoryLabels[category]+' ile ilgili Google yorumları';reviews.append(heading);const cards=document.createElement('div');cards.className='review-cards';const found=reviewData[category]||[];if(found.length){for(const r of found){const card=document.createElement('article');card.className='review-card';const stars=document.createElement('div');stars.className='review-stars';stars.textContent='★★★★★';stars.setAttribute('aria-label','5 yıldız');const q=document.createElement('blockquote');q.textContent='“'+r.text+'”';const n=document.createElement('strong');n.textContent=r.name;const small=document.createElement('small');small.textContent='Google · '+r.date+' · 1 Kasım 2026 tarihinde kontrol edildi'+(r.context?' · '+r.context:'');card.append(stars,q,n,document.createElement('br'),small);cards.append(card)}reviews.append(cards)}else{const p=document.createElement('p');p.className='lead';p.textContent='Google yorumlarında bu ürün grubunu açıkça belirten bir yorum bulunamadı. İşletmenin genel müşteri yorumlarını Google üzerinden okuyabilirsiniz.';reviews.append(p)}const a=document.createElement('a');a.className='google-source';a.href='https://www.google.com/maps?cid=6213927876677764775&hl=tr';a.target='_blank';a.rel='noopener noreferrer';a.textContent='Fotoğraf ve yorum kaynağı: Google Haritalar ↗';reviews.append(a);}
function openPhoto(list,index,button){activePhotos=list;activeIndex=index;lastPhotoButton=button;updatePhoto();document.getElementById('photo-dialog').showModal();document.body.style.overflow='hidden'}
function updatePhoto(){const p=activePhotos[activeIndex],img=document.getElementById('photo-large');img.onerror=()=>{if(img.src!==p.url){img.onerror=null;img.src=p.url}};img.src=photoURL(p.id);img.alt='Tuval Cam '+categoryLabels[p.category]+' fotoğrafı';document.getElementById('photo-caption').textContent=categoryLabels[p.category]+' · '+(activeIndex+1)+' / '+activePhotos.length+' · Google işletme ve müşteri paylaşımları'}
function initPhotoDialog(){const d=document.getElementById('photo-dialog');document.getElementById('photo-close').onclick=()=>d.close();document.getElementById('photo-prev').onclick=()=>{activeIndex=(activeIndex-1+activePhotos.length)%activePhotos.length;updatePhoto()};document.getElementById('photo-next').onclick=()=>{activeIndex=(activeIndex+1)%activePhotos.length;updatePhoto()};d.onclose=()=>{document.body.style.overflow='';lastPhotoButton?.focus()};d.addEventListener('click',e=>{if(e.target===d)d.close()});d.addEventListener('keydown',e=>{if(e.key==='ArrowRight')document.getElementById('photo-next').click();if(e.key==='ArrowLeft')document.getElementById('photo-prev').click()});let startX=0;d.addEventListener('touchstart',e=>startX=e.changedTouches[0].clientX,{passive:true});d.addEventListener('touchend',e=>{const diff=e.changedTouches[0].clientX-startX;if(Math.abs(diff)>60)document.getElementById(diff<0?'photo-next':'photo-prev').click()},{passive:true});document.querySelectorAll('[data-workshop]').forEach(b=>b.onclick=()=>{const list=galleryData.filter(p=>p.category==='atolye');openPhoto(list,list.findIndex(p=>p.id===Number(b.dataset.workshop)),b)})}
